// Settings > About > Third-party licences: the licence of everything Straft Studio ships or downloads
// (the AI engine and models, the PDF fonts, the libraries) with the full texts their licences ask to
// be passed on. `third-party-notices.json` is generated by `npm run licenses`
// (scripts/license-inventory.mjs) and loaded only when the person asks for it.

import { useState } from "react";
import { Banner, Button } from "../../design-system";
import { GEMMA_NOTICE, GEMMA_POLICY } from "../../ai/model";

type Notices = {
  ai: { name: string; text: string }[];
  fonts: { file: string; family: string; license: string; source: string; text: string }[];
  packages: { name: string; version: string; license: string; source: string; texts: string[] }[];
  texts: Record<string, string>;
};

/** One licence text, put on the page only while it is open. */
function Text({ summary, text }: { summary: string; text: string | undefined }) {
  const [open, setOpen] = useState(false);
  return (
    <details onToggle={(e) => setOpen(e.currentTarget.open)}>
      <summary className="sm">{summary}</summary>
      {open && (
        <pre className="xs selectable-text" style={{ whiteSpace: "pre-wrap", margin: "6px 0 10px" }}>
          {text}
        </pre>
      )}
    </details>
  );
}

function NoticeList({ data }: { data: Notices }) {
  // The fonts share a few licence files; each file is listed once with the fonts it covers.
  const fontTexts = [...new Set(data.fonts.map((f) => f.text))];
  return (
    <>
      <h3 className="sm" style={{ margin: "12px 0 4px" }}>
        Straft AI engine and models
      </h3>
      {data.ai.map((n) => (
        <Text key={n.name} summary={data.texts[n.text]?.split("\n")[0] ?? n.name} text={data.texts[n.text]} />
      ))}
      <h3 className="sm" style={{ margin: "12px 0 4px" }}>
        Fonts in exported PDFs
      </h3>
      {fontTexts.map((t) => (
        <Text
          key={t}
          summary={`${[...new Set(data.fonts.filter((f) => f.text === t).map((f) => f.family.replace(/ (Regular|Bold|Italic)$/, "")))].join(", ")} (${data.fonts.find((f) => f.text === t)?.license})`}
          text={data.texts[t]}
        />
      ))}
      <h3 className="sm" style={{ margin: "12px 0 4px" }}>
        Libraries ({data.packages.length})
      </h3>
      {data.packages.map((p) => (
        <Text
          key={`${p.name}@${p.version}`}
          summary={`${p.name} ${p.version} (${p.license})`}
          text={
            p.texts.length
              ? p.texts.map((t) => data.texts[t]).join("\n\n")
              : `This package carries no licence file of its own. Its declared licence is ${p.license}. Source: ${p.source}`
          }
        />
      ))}
    </>
  );
}

export function ThirdPartyNotices() {
  const [data, setData] = useState<Notices | null>(null);
  const [failed, setFailed] = useState(false);
  const show = () => {
    setFailed(false);
    import("./third-party-notices.json")
      .then((m) => setData(m.default as Notices))
      .catch(() => setFailed(true));
  };
  return (
    <div>
      <p className="sm" style={{ marginTop: 0 }}>
        Straft Studio is built with open-source libraries, fonts and AI models made by others. Their licences and notices are listed here.
      </p>
      <p className="xs muted">
        {GEMMA_NOTICE} {GEMMA_POLICY}
      </p>
      {failed && <Banner tone="err">Straft Studio could not show the notices right now. Try again.</Banner>}
      {data ? (
        <NoticeList data={data} />
      ) : (
        <Button size="sm" onClick={show}>
          Show licences and notices
        </Button>
      )}
    </div>
  );
}
